pub fn loader_icon_svg(loader: LoaderKind) -> &'static str {
    match loader {
        LoaderKind::Vanilla => SVG_VANILLA,
        LoaderKind::Fabric => SVG_FABRIC,
        LoaderKind::Quilt => SVG_QUILT,
        LoaderKind::NeoForge => SVG_NEOFORGE,
        LoaderKind::Forge => SVG_FORGE,
    }
}

pub fn icon_svg<'a>(raw_svg: &'static str, size: f32, color: Color) -> Svg<'a> {
    let px = size.round().max(12.0);
    iced::widget::svg(Handle::from_memory(raw_svg.as_bytes()))
        .width(px)
        .height(px)
        .style(move |_, _| svg::Style { color: Some(color) })
}
